fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"actual original Energy frontier exceeds4096: {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
struct OriginalConstruction{grant:RetainedCloneGrant,issued:bool}
impl semio_framework_value_native_owned::native_decoding::NativeDecodeConstructionRecipient for OriginalConstruction{
 fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,semio_framework_value::ValueError>{assert!(!self.issued);assert!(semio_framework_value::retained_clone::retained_clone_grant_admits(self.grant,d));self.issued=true;Ok(self.grant)}
 fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),semio_framework_value::ValueError>{assert!(self.issued);assert_eq!(g,self.grant);assert!(p.fits(g));Ok(())}
}
fn advance_original<T,R:NativeReceiver<DslValue,T>>(receiver:&mut R,original:semio_framework_value::retained_clone::RetainedCloneRef<'_,DslValue>,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedCloneStep,semio_framework_value::ValueError>{let mut recipient=OriginalConstruction{grant:g,issued:false};control.with_construction_recipient(&mut recipient,|control|receiver.advance(original,control,4096,g))}
fn observe<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!heap.overflowed);(result,(heap.requested_bytes,heap.released_bytes))}
fn drain<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("actual State owner supports controlled retirement"));for _ in 0..100000{if owner.terminal_is_empty(){return;}let g=grant(owner.next_demand(4096).unwrap());let(step,heap)=observe(||owner.step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("State owner did not settle original retirement");}
fn source<T:RetireOwned+Sync>(value:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let g=RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),..grant(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})};RetainedCloneSource::admit_owned(value,(),g).unwrap_or_else(|_|panic!("original State source admission")).0}
fn wire(json:&serde_json::Value)->DslValue{match json{serde_json::Value::Null=>DslValue::Null,serde_json::Value::Bool(v)=>DslValue::Bool(*v),serde_json::Value::String(v)=>DslValue::String(v.clone()),serde_json::Value::Number(v)=>DslValue::Number(if let Some(v)=v.as_u64(){semio_framework_value::Number::UInt(v)}else{semio_framework_value::Number::Float(v.as_f64().unwrap())}),serde_json::Value::Array(v)=>DslValue::Array(v.iter().map(wire).collect()),serde_json::Value::Object(v)=>DslValue::Object(v.iter().map(|(key,value)|(key.clone(),wire(value))).collect())}}
fn receive<T:NativeReceive<DslValue>>(json:&serde_json::Value)->T{
 let original=source(wire(json));let d=T::receive_birth_demand();let(mut receiver,p)=T::begin_receive(grant(d)).unwrap();assert!(p.fits(grant(d)));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);
 for _ in 0..100000{if receiver.output_ready(){break;}let d=receiver.demands(original.borrow(),4096).unwrap();let g=grant(d);let mut denied=g;denied.maximum_items=0;let(step,heap)=observe(||advance_original(&mut receiver,original.borrow(),&mut control,denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));let(step,heap)=observe(||advance_original(&mut receiver,original.borrow(),&mut control,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 assert!(receiver.output_ready());let g=grant(receiver.take_demand().unwrap());let((output,p),heap)=observe(||receiver.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));receiver.begin_close();for _ in 0..100000{if receiver.terminal_is_empty(){break;}let g=grant(receiver.close_demands(4096).unwrap());let(step,heap)=observe(||receiver.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(receiver.terminal_is_empty());drain(original);output
}
#[test]
fn energy_state_fixed_native_projection_and_sparse_plan_frames_fit4096(){
 macro_rules! projection{($($kind:ty),*)=>{$(let(d,heap)=observe(<$kind as SnapshotProjection>::projection_birth_demand);assert_eq!(heap,(0,0));assert!(d.copy_bytes<=4096,"{} actual projection frame={d:?}",stringify!($kind));eprintln!("[DEBUG] Energy {} original projection frame copy={}",stringify!($kind),d.copy_bytes);)*};}
 projection!(EnergyModelState,ModelIdentityState,ModelGeometryState,ModelMaterialState,ModelLoadState,ModelControlState,ModelSystemState,ModelGenerationState,ModelOutputState,StateScheduleSet,StateZone,StateSurface,StateFenestration,StateInfiltration);
 macro_rules! sparse{($($fields:ty),*)=>{$(let bytes=std::mem::size_of::<$fields>()+std::mem::size_of::<Option<$fields>>()+std::mem::size_of::<usize>()+std::mem::size_of::<u8>();assert!(bytes<=4096,"{} actual shared sparse frame copy={bytes}",stringify!($fields));eprintln!("[DEBUG] Energy {} original sparse plan frame copy={bytes}",stringify!($fields));)*};}
 sparse!(diff::state_zone_fields::Fields,diff::state_fenestration_fields::Fields,diff::state_infiltration_fields::Fields);
}
#[test]
fn energy_state_original_zone_receive_projection_and_inverse_preserve_paid_authority(){
 let law=corpus();let whole=receive::<EnergyModelState>(&law["model"]);assert_eq!(semio_framework_value::ToValue::to_value(&whole),wire(&law["model"]));assert_eq!(whole.geometry.get().zones.len(),1);assert_eq!(whole.identity.get().name.get(),law["model"]["name"].as_str().unwrap());drain(whole);for refusal in law["refusals"].as_array().unwrap(){let original=source(receive::<StateZone>(&law["cases"][1]["before"]["zones"][0]));let mut post=PostFixture::new(project_zone(&original));let pointer=post.name.get().as_ptr();let identity=post.name.identity();let patch=source(receive::<diff::StateZonePatch>(&refusal["patch"]));assert!(!central_zone(&patch,&original,&mut post));assert_eq!(&post,original.borrow().get());assert_eq!(post.name.get().as_ptr(),pointer);assert_eq!(post.name.identity(),identity);drain(patch);drain(post.into_inner());drain(original);}for case in law["cases"].as_array().unwrap().iter().filter(|case|case["id"]=="zone-label"||case["id"]=="zone-volume"){
  let operation=&case["forward"][0];let path=operation["path"].as_str().unwrap().split('/').collect::<Vec<_>>();let rank=path[2].parse::<usize>().unwrap();let original=source(receive::<StateZone>(&case["before"]["zones"][rank]));let base=original.borrow();let pointer=base.get().name.get().as_ptr();let original_identity=base.get().name.identity();
  let d=StateZone::projection_birth_demand();let(mut cursor,_)=StateZone::begin_projection(grant(d)).unwrap();for _ in 0..100000{if cursor.ready(){break;}let g=grant(cursor.demands(original.borrow(),4096).unwrap());let(step,heap)=observe(||cursor.advance(original.borrow(),g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.ready());let g=grant(cursor.take_demand().unwrap());let(post,p)=cursor.take(g).unwrap().unwrap();let mut post:PostFixture<StateZone>=PostFixture::projected(post);assert!(p.fits(g));assert_eq!(post.name.identity(),original_identity);assert_eq!(post.name.get().as_ptr(),pointer);cursor.begin_close();for _ in 0..100000{if cursor.terminal_is_empty(){break;}let g=grant(cursor.close_demands(4096).unwrap());let(step,heap)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.terminal_is_empty());
  let field=path[3];let mut patch=serde_json::Map::new();patch.insert(field.to_owned(),operation["value"].clone());let authored=source(receive::<diff::StateZonePatch>(&serde_json::Value::Object(patch)));let mut inverse=diff::state_zone_fields::Fields::new(RetainedPatchSource::Inverse);for _ in 0..100000{let g=grant(inverse.demand(authored.borrow(),original.borrow(),4096).unwrap());let(step,heap)=observe(||inverse.advance(authored.borrow(),original.borrow(),g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,RetainedCloneStep::Complete(_)){break;}}
  let g=grant(RetirementDemand{copy_bytes:std::mem::size_of::<diff::StateZonePatch>()*2,depth:1,..Default::default()});let(undo,p)=inverse.take(g).unwrap();assert!(p.fits(g));let undo=undo.unwrap();if field=="name"{assert_eq!(undo.name.as_ref().unwrap().get(),case["inverse"][0]["value"].as_str().unwrap());assert_eq!(undo.name.as_ref().unwrap().identity(),original_identity);}else{assert_eq!(undo.volume_m3,case["inverse"][0]["value"].as_f64());assert!(undo.name.is_none());}inverse.begin_close();for _ in 0..100000{if inverse.terminal_is_empty(){break;}let g=grant(inverse.close_demand(4096).unwrap());let(step,heap)=observe(||inverse.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(inverse.terminal_is_empty());assert_eq!(original.borrow().get().name.get().as_ptr(),pointer);assert!(central_zone(&authored,&original,&mut post));assert_eq!(post.id,original.borrow().get().id);if field=="name"{assert_eq!(post.name.get(),case["after"]["zones"][rank]["name"].as_str().unwrap());}else{assert_eq!(post.volume_m3,case["after"]["zones"][rank]["volume_m3"].as_f64().unwrap());assert_eq!(post.name.identity(),original_identity);}let changed=source(post.into_inner());let mut restored=PostFixture::new(project_zone(&changed));let undo=source(undo);assert!(central_zone(&undo,&changed,&mut restored));assert_eq!(&restored,original.borrow().get());assert_eq!(restored.name.identity(),original_identity);drain(restored.into_inner());drain(undo);drain(authored);drain(changed);drain(original);eprintln!("[DEBUG] Energy original {:?} native receiving/projection/inverse preserves actual name authority and exact paid allocations",case["id"]);
 }
}
fn denied_axes(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut result=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{result.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g});}if d.capacity_bytes>0{result.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g});}if d.release_bytes>0{result.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g});}if d.depth>0{result.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g});}result}
fn project_zone(original:&RetainedCloneSource<StateZone>)->StateZone{
 let d=StateZone::projection_birth_demand();let(mut cursor,_)=StateZone::begin_projection(grant(d)).unwrap();for _ in 0..100000{if cursor.ready(){break;}let g=grant(cursor.demands(original.borrow(),4096).unwrap());let(step,heap)=observe(||cursor.advance(original.borrow(),g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.ready());let g=grant(cursor.take_demand().unwrap());let((post,p),heap)=observe(||cursor.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));cursor.begin_close();for _ in 0..100000{if cursor.terminal_is_empty(){break;}let g=grant(cursor.close_demands(4096).unwrap());let(step,heap)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.terminal_is_empty());post
}
fn central_zone(patch:&RetainedCloneSource<diff::StateZonePatch>,original:&RetainedCloneSource<StateZone>,post:&mut PostFixture<StateZone>)->bool{
 use protocol::mutation::retained::{begin_retained_diff,retained_diff_birth_demand,preflight_retained_diff,commit_retained_diff,RetainedDiffPreflightStep};
 let d=retained_diff_birth_demand::<StateZone,diff::StateZonePatch>();let g=grant(d);let((mut owner,p),heap)=observe(||begin_retained_diff::<StateZone,diff::StateZonePatch>(g).unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut admitted=None;
 for _ in 0..100000{let d=owner.preflight_demand(patch.borrow(),original.borrow(),post.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||preflight_retained_diff(&mut owner,patch.borrow(),original.borrow(),post.borrow(),4096,denied,&mut control).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.preflight_demand(patch.borrow(),original.borrow(),post.borrow(),4096).unwrap(),d);}let(step,heap)=observe(||preflight_retained_diff(&mut owner,patch.borrow(),original.borrow(),post.borrow(),4096,g,&mut control).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));match step{RetainedDiffPreflightStep::Admitted(_,messages)=>{assert!(messages.is_empty());admitted=Some(true);break;},RetainedDiffPreflightStep::Refused(_,messages)=>{assert!(messages.is_empty());admitted=Some(false);break;},_=>{}}}
 let admitted=admitted.expect("original central Zone preflight settles");if admitted{owner.inverse_admission(patch.borrow(),original.borrow()).unwrap();let mut complete=false;for _ in 0..100000{let d=owner.commit_demand(patch.borrow(),original.borrow(),post.mutable_read(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||commit_retained_diff(&mut owner,patch.borrow(),original.borrow(),post,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.commit_demand(patch.borrow(),original.borrow(),post.borrow(),4096).unwrap(),d);}let(step,heap)=observe(||commit_retained_diff(&mut owner,patch.borrow(),original.borrow(),post,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,RetainedCloneStep::Complete(_)){complete=true;break;}}assert!(complete);}
 owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.close_demand(4096).unwrap(),d);}let(step,heap)=observe(||owner.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(owner.terminal_is_empty());admitted
}